import asyncio
from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient
from functools import cache
from functools import wraps
from typing import Awaitable, Callable, Generic, Iterator, ParamSpec, TypeVar
from pydantic import BaseSettings

# --- Setup from problem description ---

P = ParamSpec('P')
T = TypeVar('T')

class Reawaitable(Generic[T]):
    __sentinel = object()

    def __init__(self, awaitable: Awaitable[T]) -> None:
        self.awaitable = awaitable
        self.result = self.__sentinel

    def __await__(self) -> Iterator[T]:
        if self.result is self.__sentinel:
            self.result = yield from self.awaitable.__await__()
        return self.result


def reawaitable(func: Callable[P, Awaitable[T]]) -> Callable[P, Reawaitable[T]]:
    @wraps(func)
    def wrapper(*args: P.args, **kwargs: P.kwargs) -> Reawaitable[T]:
        return Reawaitable(func(*args, **kwargs))
    return wrapper


class Settings(BaseSettings):
    foo: str = 'bar'


app = FastAPI()


@cache
@reawaitable
async def get_settings() -> Settings:
    print("--- get_settings called ---")
    return Settings()


@app.get('/foo')
async def foo(settings: Settings = Depends(get_settings)) -> str:
    print("--- /foo endpoint called ---")
    return settings.foo

# --- Test Execution ---

client = TestClient(app)

print("--- First request to /foo ---")
response1 = client.get("/foo")
assert response1.status_code == 200
assert response1.json() == {"foo": "bar"}
print("First request successful.")

print("\n--- Second request to /foo (should use cache) ---")
response2 = client.get("/foo")
assert response2.status_code == 200
assert response2.json() == {"foo": "bar"}
print("Second request successful (cache hit expected).")

print("\n--- Test complete ---")
